css:
/* Отрицательные margin-right гасят фантомный отступ, который трекинг
   добавляет справа от последней буквы — иначе блок надписи съезжает. */
.bm__name--thin {
	font-family: var(--font-heading);
	font-weight: 300;
	font-size: 21px;
	letter-spacing: 0.30em;
	margin-right: -0.30em;
}
.bm__sub--thin {
	font-weight: 400;
	font-size: 10px;
	letter-spacing: 0.34em;
	margin-right: -0.34em;
}
@media (max-width: 1100px) { .bm__name--thin { font-size: 17px; letter-spacing: 0.2em; margin-right: -0.2em; } }

/* Монограмма чуть плотнее: тонкий сериф рядом с Montserrat 800
   читался бы как два разных логотипа. */
.bm__mono { font-weight: 600; }
.bm__name--bold {
	font-family: var(--font-heading);
	font-weight: 800;
	font-size: 22px;
	letter-spacing: 0.02em;
}
.bm__sub--bold {
	font-weight: 700;
	font-size: 10px;
	letter-spacing: 0.26em;
	margin-right: -0.26em;
}
@media (max-width: 1100px) { .bm__name--bold { font-size: 18px; } }
